using Clary.Api.Identity;
using Npgsql;
using NpgsqlTypes;
namespace Clary.Api;
public sealed partial class TicketRepository {
 internal async Task AdoptRequest(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,EquipmentRequest request,string action,CancellationToken ct){
  var creator=action=="Created";var approve=action is "approve" or "approve-and-assign";var state=request.State switch{"Ready"=>"Assigned","Completed"=>"Complete","Cancelled"=>"Canceled",_=>request.State};
  await using(var q=Q(conn,tx,c,"UPDATE equipment_tickets SET state=@state,type=@type,description=@notes,due_date=@due,recipient_employee_id=@recipient,department_id=@department,location_id=@location,creator_user_id=CASE WHEN @created THEN @user ELSE creator_user_id END,creator_name=CASE WHEN @created THEN @actor ELSE creator_name END,approver_user_id=CASE WHEN @approve THEN @user ELSE approver_user_id END,approver_name=CASE WHEN @approve THEN @actor ELSE approver_name END,approved_at=CASE WHEN @approve THEN now() ELSE approved_at END WHERE company_id=@company AND id=@ticket")){q.Parameters.AddWithValue("state",state);q.Parameters.AddWithValue("type",request.Purpose);P(q,"notes",request.Notes,NpgsqlDbType.Text);P(q,"due",request.NeededDate,NpgsqlDbType.Date);q.Parameters.AddWithValue("recipient",request.EmployeeId);P(q,"department",request.DepartmentId,NpgsqlDbType.Uuid);P(q,"location",request.LocationId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("created",creator);q.Parameters.AddWithValue("approve",approve);q.Parameters.AddWithValue("actor",await Actor(conn,tx,c,ct));q.Parameters.AddWithValue("ticket",request.TicketId);await q.ExecuteNonQueryAsync(ct);}
  await using(var q=Q(conn,tx,c,"INSERT INTO ticket_asset_links(company_id,ticket_id,asset_id,outcome,baseline_revision,baseline_status,baseline_employee_id,baseline_assignee,baseline_location_id,owned_revision) SELECT @company,@ticket,a.id,'Assign',a.revision,a.status,a.employee_id,a.assignee,a.location_id,a.revision FROM inventory_assets a JOIN equipment_request_assets x ON x.company_id=a.company_id AND x.asset_id=a.id WHERE a.company_id=@company AND x.request_id=@request ON CONFLICT(company_id,ticket_id,asset_id) DO UPDATE SET owned_revision=excluded.owned_revision,baseline_revision=excluded.baseline_revision")){q.Parameters.AddWithValue("ticket",request.TicketId);q.Parameters.AddWithValue("request",request.Id);await q.ExecuteNonQueryAsync(ct);}
  if(creator&&request.Purpose=="Onboarding"){await using var q=Q(conn,tx,c,"INSERT INTO ticket_document_links(company_id,ticket_id,id,document_id,document_title) SELECT @company,@ticket,@id,d.id,d.title FROM ticket_settings s JOIN documents d ON d.company_id=s.company_id AND d.id=s.onboarding_document_id WHERE s.company_id=@company ON CONFLICT DO NOTHING");q.Parameters.AddWithValue("ticket",request.TicketId);q.Parameters.AddWithValue("id",Guid.NewGuid());await q.ExecuteNonQueryAsync(ct);}
  await Activity(conn,tx,c,request.TicketId,creator?"Created":state,"Linked equipment request",ct);
 }
 internal async Task<TicketDto> RequestAction(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext c,Guid ticket,string action,CancellationToken ct){var current=await Get(conn,tx,c,ticket,ct)??throw new InventoryMissing();return await ActionWithin(conn,tx,c,ticket,new(action,current.Revision),ct);}
}
